using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using ColdWarStruggle.Core;
using ColdWarStruggle.Application;
using ColdWarStruggle.Presentation;
using Newtonsoft.Json;
using NUnit.Framework;
namespace ColdWarStruggle.Tests
{
    public class PlayOpponentInfluenceSessionTests
    {
        static CountryId C(string s)=>PlayOpponentInfluenceTests.C(s);
        static CardActionTransition Start(GameState s,bool first)=>PlayOpponentInfluenceTests.Start(s,"card.duck_and_cover",first);
        [TestCase(true,2,0,VictoryCheckpoint.NuclearWarReached)][TestCase(false,2,0,VictoryCheckpoint.NuclearWarReached)]
        [TestCase(true,5,19,VictoryCheckpoint.VpBatchClosed)][TestCase(false,5,19,VictoryCheckpoint.VpBatchClosed)]
        public void Terminal_event_stops_remainder_and_keeps_phasing_responsibility_and_accepted_ops_prefix(bool first,int level,int vp,VictoryCheckpoint checkpoint)
        {
            var s=PlayDefconVpEventTests.Ready(level:level,vp:vp);var start=Start(s,first);Assert.That(start.Accepted,Is.True);var n=start.NextState;int old=s.GetInfluence(C("nigeria"),PlayerSide.USSR);
            if(!first){Assert.That(n.Ended,Is.False);var placed=InfluenceRules.PlanPlacement(n,n.Operations,new[]{C("nigeria")});Assert.That(placed.Accepted,Is.True);var finished=PlayOpponentInfluenceTests.Finish(placed.NextState);Assert.That(finished.Accepted,Is.True);Assert.That(finished.DefconVpEvent.Decision.Outcome,Is.EqualTo(VictoryOutcome.Finished));n=finished.NextState;}
            Assert.That(n.Ended,Is.True);Assert.That(n.Practice.Risk.Result.Winner,Is.EqualTo(PlayerSide.US));Assert.That(n.Practice.Risk.Result.Checkpoint,Is.EqualTo(checkpoint));Assert.That(n.Practice.CompletedActions,Is.Zero);Assert.That(n.Cards.ResolvingCards,Is.EqualTo(new[]{new CardId("card.duck_and_cover")}));Assert.That(n.Cards.DiscardPile,Is.Empty);Assert.That(n.GetInfluence(C("nigeria"),PlayerSide.USSR),Is.EqualTo(old+(first?0:1)));Assert.That(n.Operations.Budget,Is.Zero);Assert.That(PlayOpponentInfluenceTests.Finish(n).Error,Is.EqualTo(RuleError.GameAlreadyEnded));Pcg32RandomTests.Same(s.RandomState,n.RandomState);
        }
        [TestCase(true)][TestCase(false)] public void Version_or_sequence_overflow_never_publishes_start_or_finalization(bool version)
        {
            var s=PlayRealignmentTests.Ready("card.containment");s=PlayScoringTests.Replace(s,version:version?long.MaxValue:(long?)null,sequence:version?null:(long?)long.MaxValue);var a=PlayOpponentInfluenceTests.Start(s,"card.containment",true);Assert.That(a.Error,Is.EqualTo(RuleError.NumericOverflow));Assert.That(s.Practice.OpsEffects.Instances,Is.Empty);Assert.That(s.Cards.ResolvingCards,Is.Empty);
            var original=PlayRealignmentTests.Ready("card.containment");var pending=PlayOpponentInfluenceTests.Start(original,"card.containment",false).NextState;var place=InfluenceRules.PlanPlacement(pending,pending.Operations,new[]{C("nigeria")});Assert.That(place.Accepted,Is.True);pending=PlayScoringTests.Replace(place.NextState,version:version?long.MaxValue:(long?)null,sequence:version?null:(long?)long.MaxValue);var end=PlayOpponentInfluenceTests.Finish(pending);Assert.That(end.Error,Is.EqualTo(RuleError.NumericOverflow));Assert.That(end.NextState,Is.Null);Assert.That(pending.SpentOps,Is.EqualTo(1));Assert.That(pending.Practice.OpsEffects.Instances,Is.Empty);Assert.That(pending.Practice.OpponentOps.CompletedSteps,Is.Zero);Assert.That(pending.Cards.ResolvingCards.Count,Is.EqualTo(1));
        }
        [TestCase(true)][TestCase(false)] public async Task Choice_finalization_overflow_returns_no_partial_removal_or_root_progress(bool first)
        {
            var s=PlayOpponentInfluenceTests.ReadyUS("card.suez_crisis");s=PlayInfluenceEventTests.Copy(s,version:long.MaxValue-(first?3:5));var a=PlayOpponentInfluenceTests.Start(s,"card.suez_crisis",first);Assert.That(a.Accepted,Is.True);var pending=first?a.NextState:PlayOpponentInfluenceTests.Finish(a.NextState).NextState;Assert.That(pending.Version,Is.EqualTo(long.MaxValue-1));
            var h=new LocalGameHost(pending,true);var session=h.UssrSession;var v=session.ReadView();var q=session.QueryEventTargets(v.Event.ExecutionId,v.Version);var left=q.RequiredAmount;var allocations=new List<InfluenceAllocation>();foreach(var cap in q.Capacities){var amount=Math.Min(left,cap.Amount);if(amount>0)allocations.Add(new InfluenceAllocation(cap.Country,amount));left-=amount;}Assert.That(left,Is.Zero);
            var command=EventCommandEnvelope.Allocate("overflow",v.GameId,v.Version,v.Event.ExecutionId,v.Event.DecisionId,allocations);var r=await session.SubmitEventAsync(command);Assert.That(r.Error,Is.EqualTo(RuleError.NumericOverflow));Assert.That(await session.SubmitEventAsync(command),Is.SameAs(r));var after=session.ReadView();Assert.That(after.Version,Is.EqualTo(v.Version));Assert.That(after.Practice.CompletedActions,Is.EqualTo(v.Practice.CompletedActions));Assert.That(after.Practice.OpponentOps.CompletedSteps,Is.EqualTo(v.Practice.OpponentOps.CompletedSteps));Assert.That(after.Cards.ResolvingCount,Is.EqualTo(1));foreach(var country in after.Countries){var before=v.Countries.Single(x=>x.Definition.Id.Equals(country.Definition.Id));Assert.That(country.US,Is.EqualTo(before.US));Assert.That(country.USSR,Is.EqualTo(before.USSR));}
        }
        [Test] public void Event_first_removal_recomputes_ops_reachability_after_the_event()
        {
            var s=PlayRealignmentTests.Ready("card.truman_doctrine");var board=RegionScoringTests.Empty(s.Map);board[C("france")]=new CountryState(0,1);s=PlayScoringTests.Replace(s,board);var a=PlayOpponentInfluenceTests.Start(s,"card.truman_doctrine",true);Assert.That(a.Accepted,Is.True);var e=a.NextState.InfluenceEvent;var raw=InfluenceEventFlow.Resolve(a.NextState,e.Owner,e.DecisionId,new[]{C("france")});Assert.That(raw.Accepted,Is.True);var done=ActionPracticeRules.CompleteEventAction(raw);Assert.That(done.Accepted,Is.True);Assert.That(done.NextState.GetInfluence(C("france"),PlayerSide.USSR),Is.Zero);Assert.That(done.NextState.Operations.Reachable,Has.No.Member(C("spain_portugal")));Assert.That(done.NextState.Practice.OpponentOps.CurrentStep,Is.EqualTo(CardResolutionStep.Operations));Assert.That(done.NextState.Cards.ResolvingCards.Count,Is.EqualTo(1));
        }
        [Test] public async Task Real_default_hand_options_and_public_progress_keep_private_data_out_and_replay_exactly()
        {
            var c=PlayRealignmentCatalogTests.Catalog();var h=c.CreateHost(c.Scenarios.Last().Id);var session=h.UssrSession;var v=session.ReadView();var id=new CardId("card.duck_and_cover");var option=session.QueryCardActions().Cards.Single(x=>x.Card.Equals(id));Assert.That(option.EventThenInfluence,Is.EqualTo(RuleError.None));Assert.That(option.InfluenceThenEvent,Is.EqualTo(RuleError.None));Assert.That(option.Influence,Is.EqualTo(RuleError.UnsupportedCardAction));Assert.That(option.Coup,Is.EqualTo(RuleError.UnsupportedCardAction));Assert.That(option.Realignment,Is.EqualTo(RuleError.UnsupportedCardAction));
            var cmd=new CardActionCommand("order",v.GameId,v.Version,CardActionKind.EventThenInfluence,id);var r=await session.SubmitCardActionAsync(cmd);Assert.That(r.Accepted,Is.True);var p=r.View.Practice.OpponentOps;Assert.That(p.Card,Is.EqualTo(id));Assert.That(p.Actor,Is.EqualTo(PlayerSide.USSR));Assert.That(p.EventSide,Is.EqualTo(PlayerSide.US));Assert.That(p.Order,Is.EqualTo(OpponentEventOrder.EventFirst));Assert.That(p.CurrentStep,Is.EqualTo(CardResolutionStep.Operations));Assert.That(p.CompletedSteps,Is.EqualTo(1));Assert.That(p.EventOccurred,Is.True);Assert.That(r.View.Practice.CompletedActions,Is.Zero);Assert.That(r.View.RemainingOps,Is.EqualTo(3));Assert.That(await session.SubmitCardActionAsync(cmd),Is.SameAs(r));
            Assert.That((await session.SubmitCardActionAsync(new CardActionCommand("order",v.GameId,v.Version,CardActionKind.InfluenceThenEvent,id))).Error,Is.EqualTo(RuleError.CommandIdConflict));Assert.That((await session.SubmitCardActionAsync(new CardActionCommand("old",v.GameId,v.Version,CardActionKind.EventThenInfluence,id))).Error,Is.EqualTo(RuleError.StaleVersion));Assert.That(h.UsSession.ReadView().Practice.OpponentOps.CurrentStep,Is.EqualTo(p.CurrentStep));var json=JsonConvert.SerializeObject(p);Assert.That(json,Does.Not.Contain("Random").And.Not.Contain("Seed").And.Not.Contain("Definition").And.Not.Contain("Hand"));
            var now=session.ReadView();var finish=new CardActionCommand("finish",now.GameId,now.Version,CardActionKind.FinishInfluence);var done=await session.SubmitCardActionAsync(finish);Assert.That(done.Accepted,Is.True);Assert.That(done.View.Practice.OpponentOps,Is.Null);Assert.That(done.View.Practice.CompletedActions,Is.EqualTo(1));Assert.That(await session.SubmitCardActionAsync(finish),Is.SameAs(done));Assert.That(await session.SubmitCardActionAsync(cmd),Is.SameAs(r));Assert.That(session.ReadView().Version,Is.EqualTo(done.View.Version));
        }
        [TestCase(true)][TestCase(false)] public async Task Controller_routes_order_choice_and_returns_to_original_actor_after_opponent_choice(bool first)
        {
            var h=new LocalGameHost(PlayOpponentInfluenceTests.ReadyUS("card.suez_crisis"),true);var c=new DemoController(_=>h);c.LoadScenario("test",PlayerSide.US,C("france"));c.SelectCard(new CardId("card.suez_crisis"));var r=await c.PlayCardAsync(first?CardActionKind.EventThenInfluence:CardActionKind.InfluenceThenEvent);Assert.That(r.Accepted,Is.True);Assert.That(c.SelectedCard,Is.Null);if(!first)Assert.That((await c.FinishInfluenceAsync()).Accepted,Is.True);var pending=c.ReadView();Assert.That(pending.Event.Owner,Is.EqualTo(PlayerSide.USSR));c.SelectSide(PlayerSide.USSR);var q=c.EventTargets();Assert.That(q.Error,Is.EqualTo(RuleError.None));
            var left=q.RequiredAmount;var a=new List<InfluenceAllocation>();foreach(var cap in q.Capacities){var n=Math.Min(cap.Amount,left);if(n>0)a.Add(new InfluenceAllocation(cap.Country,n));left-=n;}Assert.That(left,Is.Zero);var v=c.ReadView();var cmd=EventCommandEnvelope.Allocate("resolve",v.GameId,v.Version,v.Event.ExecutionId,v.Event.DecisionId,a);var accepted=await h.UssrSession.SubmitEventAsync(cmd);Assert.That(accepted.Accepted,Is.True);Assert.That(await h.UssrSession.SubmitEventAsync(cmd),Is.SameAs(accepted));
            if(first){Assert.That(c.ReadView().Practice.Actor,Is.EqualTo(PlayerSide.US));Assert.That(c.LegalTargets().Error,Is.EqualTo(RuleError.WrongActor));c.SelectSide(PlayerSide.US);Assert.That(c.LegalTargets().Error,Is.EqualTo(RuleError.None));Assert.That((await c.FinishInfluenceAsync()).Accepted,Is.True);}Assert.That(c.ReadView().Practice.CompletedActions,Is.EqualTo(2));Assert.That(c.ReadView().Practice.OpponentOps,Is.Null);
        }
    }
}
